    95  simdjson_really_inline value128 full_multiplication(uint64_t value1, uint64_t value2) {
    96    value128 answer;
    97  #if defined(SIMDJSON_REGULAR_VISUAL_STUDIO) || defined(SIMDJSON_IS_32BITS)
    98  #ifdef _M_ARM64
    99    // ARM64 has native support for 64-bit multiplications, no need to emultate
   100    answer.high = __umulh(value1, value2);
   101    answer.low = value1 * value2;
   102  #else
   103    answer.low = _umul128(value1, value2, &answer.high); // _umul128 not available on ARM64
   104  #endif // _M_ARM64
   105  #else // defined(SIMDJSON_REGULAR_VISUAL_STUDIO) || defined(SIMDJSON_IS_32BITS)
   106    __uint128_t r = ((__uint128_t)value1) * value2;
   107    answer.low = uint64_t(r);
   108    answer.high = uint64_t(r >> 64);
   109  #endif
   110    return answer;
   111  }
